"""Literal invented producer metadata; never read a retained/source payload."""
from copy import deepcopy
from fractions import Fraction
import json
import pytest
from curve_fixture import fixture
from polar.gym_contract import canonical,sha
from polar.scheduled_curve import raw_source_ref_status,plan_phase,verify_plan,CurveError,expected_counts
from polar.scheduled_service import load_market
from polar.reference_service import ReferenceResearchService

# Literal producer-shaped capture ref, not generated by the consumer validator.
REF={'path':'/INVENTED-CAPTURE.xml','sha256':'a'*64,'bytes':10000,'complete':True}


def test_closed_true_and_legacy_unknown_preserve_literal_input():
    for ref,status in [(REF,'COMPLETE'),({k:v for k,v in REF.items() if k!='complete'},'UNKNOWN')]:
        original=deepcopy(ref)
        assert raw_source_ref_status(ref)==status and ref==original


BAD=[{**REF,'complete':x} for x in (False,None,'true',1,0)] + [
    {**REF,'arbitrary':True}, *[{k:v for k,v in REF.items() if k!=field} for field in ('path','sha256','bytes')],
    *[{**REF,'sha256':x} for x in ('a'*63,'A'*64,'z'*64,None)],
    *[{**REF,'bytes':x} for x in (0,-1,True,'10000',None)],
    *[{**REF,'path':x} for x in ('relative.xml','/tmp/../capture.xml','',None,'/bad\x00path','/'+'x'*4096)]]


@pytest.mark.parametrize('ref',BAD)
def test_reject_wrong_completeness_unknown_fields_and_mandatory_domains(ref):
    with pytest.raises(ValueError,match='CURVE_RAW_SOURCE_'):raw_source_ref_status(ref)


@pytest.mark.parametrize('complete',[True,None])
def test_original_and_saved_complete_or_legacy_unknown(tmp_path,monkeypatch,complete):
    ref=dict(REF)
    if complete is None:del ref['complete']
    root,cfg,p,c,d=fixture(tmp_path,monkeypatch,raw_ref=ref)
    market=load_market(cfg,p);g=c['phases']['FINAL'];plan=plan_phase(market,p,g,None)
    status='UNKNOWN' if complete is None else 'COMPLETE'
    assert all(w['source_row']['raw_ref']==ref and w['raw_source_completeness']==status for w in plan['signals'])
    # Valid finite negative rates remain valid; zero/positive controls remain separate.
    assert any(Fraction(w['source_row']['tokens']['BC_2YEAR'])<0 for w in plan['signals'])
    verify_plan(plan,p,market['schedule'],g)
    bad=deepcopy(plan);w=bad['signals'][0];w['raw_source_completeness']='COMPLETE' if status=='UNKNOWN' else 'UNKNOWN'
    w['seal_sha256']=sha(canonical({k:v for k,v in w.items() if k!='seal_sha256'}))
    with pytest.raises(ValueError,match='CURVE_SAVED_SOURCE_COMPLETENESS'):verify_plan(bad,p,market['schedule'],g)
    for mutation in ('span','row'):
        bad=deepcopy(plan);w=bad['signals'][0]
        if mutation=='span':w['join']['byte_end_exclusive']+=1
        else:w['source_row']['raw_ref']['sha256']='b'*64
        w['seal_sha256']=sha(canonical({k:v for k,v in w.items() if k!='seal_sha256'}))
        with pytest.raises(ValueError,match='CURVE_SAVED_'):verify_plan(bad,p,market['schedule'],g)


@pytest.mark.parametrize('ref,cause',[
    ({**REF,'complete':False},'CURVE_RAW_SOURCE_COMPLETENESS'),
    ({**REF,'sha256':'z'*64},'CURVE_RAW_SOURCE_REF'),
    ({**REF,'bytes':4},'CURVE_RAW_FIELD_POINTER')])
def test_bad_capture_metadata_after_debit_keeps_counts_finish_and_no_retry(tmp_path,monkeypatch,ref,cause):
    root,cfg,p,c,d=fixture(tmp_path,monkeypatch,raw_ref=ref)
    import polar.scheduled_service as module
    monkeypatch.setattr(module,'bounded_native',lambda *a:(_ for _ in ()).throw(AssertionError('NO_NATIVE_AFTER_METADATA_FAILURE')))
    service=ReferenceResearchService(root,256*1024**2)
    # Row completeness lives in post-debit payload; preflight reads index/descriptor only.
    assert service.preflight(cfg)['expected_native_accounts']==8
    assert not (root/'scheduled-reference-attempts').exists()
    with pytest.raises(CurveError) as exc:service.run(cfg)
    assert exc.value.events['cause']==cause
    finish=json.loads(next(root.rglob('finish/record.json')).read_bytes())
    assert finish['scientific_status']=='INVALID' and finish['completed_native_accounts']==0
    assert finish['actual_feature_counts']=={**expected_counts(0),'feature_calls':1}
    assert finish['refund'] is False and finish['automatic_retry'] is False
    with pytest.raises(ValueError,match='ORIGINAL_ALREADY_RECORDED'):service.run(cfg)
